30|export function createCore(rom: Uint8Array, opts?: { model?: "DMG" | "CGB" }): Core {
31|  let model: "DMG" | "CGB";
32|  if (opts && opts.model) model = opts.model;
33|  else {
34|    const h = rom.length > 0x143 ? rom[0x143] : 0;
35|    model = (h & 0x80) !== 0 ? "CGB" : "DMG";
36|  }
37|  const isCgb = model === "CGB";
38|  const hits = newHits();
39|  const cart = new Cart(rom, hits);
40|  const ppu = new Ppu(hits);
41|  ppu.cgb = isCgb;
42|  const wram = new Uint8Array(isCgb ? 0x8000 : 0x2000);
43|  const hram = new Uint8Array(0x80);
44|  const audio = new Uint8Array(0x40);
45|  const audInit: Array<[number, number]> = [
46|    [0x10,0x80],[0x11,0xbf],[0x12,0xf3],[0x14,0xbf],[0x16,0x3f],[0x17,0x00],
47|    [0x19,0xbf],[0x1a,0x7f],[0x1b,0xff],[0x1c,0x9f],[0x1e,0xbf],[0x20,0xff],
48|    [0x21,0x00],[0x22,0x00],[0x23,0xbf],[0x24,0x77],[0x25,0xf3],[0x26,0xf1],
49|  ];
50|  for (const [o,v] of audInit) audio[o & 0x3f] = v;
51|
52|  let div = isCgb ? 0x0000 : 0xab00;
53|  let tima = 0, tma = 0, tac = 0xf8;
54|  let prevAnd = 0;
55|  let reload = 0;
56|  let IF = isCgb ? 0x00 : 0xe1;
57|  let IE = 0x00;
58|  let p1 = 0xcf;
59|  let joyMask = 0;
60|  let sb = 0x00, sc = 0x7e;
61|  let serialText = "";
62|  let dmaOn = false, dmaBase = 0, dmaPos = 0, dmaT = 0;
63|  let cycles = 0;
64|  // CGB state
65|  let key1arm = false;
66|  let dbl = false;
67|  let vbk = 0;
68|  let svbk = 1;
69|  let hdma1 = 0xff, hdma2 = 0xff, hdma3 = 0xff, hdma4 = 0xff;
70|  let hdmaActive = false;
71|  let hdmaRem = 0;
72|  let hdmaSrc = 0;
73|  let hdmaDst = 0;
74|  if (isCgb) {
75|    ppu.bgPal.fill(0xff);
76|    ppu.objPal.fill(0xff);
77|    ppu.bgpi = 0;
78|    ppu.obpi = 0;
79|  }
80|  let onRegWrite: TelemetryTap["onRegWrite"] | undefined = undefined;
81|  const tapHits = hits;
82|
83|  const raise = (b: number): void => { IF = (IF | (1 << b)) & 0xff; };
84|
85|  function timerBit(): number {
86|    const s = tac & 0x03;
87|    return s === 0 ? 9 : s === 1 ? 3 : s === 2 ? 5 : 7;
88|  }
89|  function curAnd(): number {
90|    return (((div >> timerBit()) & 1) & ((tac >> 2) & 1));
91|  }
92|  function incTima(): void {
93|    hits["timer"] = (hits["timer"] || 0) + 1;
94|    if (tima === 0xff) { tima = 0; reload = 4; }
95|    else tima = (tima + 1) & 0xff;
96|  }
97|  function timerStep(): void {
98|    if (reload > 0) {
99|      reload--;
100|      if (reload === 0) { tima = tma & 0xff; IF = (IF | 0x04) & 0xff; }
101|    }
102|    div = (div + 1) & 0xffff;
103|    const c = curAnd();
104|    if (prevAnd === 1 && c === 0) {
105|      if (reload === 0) incTima();
106|    }
107|    prevAnd = c;
108|  }
109|
110|  function wramBank(): number {
111|    if (!isCgb) return 0;
112|    return svbk === 0 ? 1 : svbk;
113|  }
114|
115|  function rdMem(a: number): number {
116|    // raw read without tick (for HDMA src)
117|    a &= 0xffff;
118|    if (a < 0x8000) return cart.read(a);
119|    if (a < 0xa000) {
120|      if (!isCgb) return ppu.vram[a - 0x8000] & 0xff;
121|      const b = vbk ? 0x2000 : 0;
122|      return ppu.vram[b + (a - 0x8000)] & 0xff;
123|    }
124|    if (a < 0xc000) return cart.readRam(a);
125|    if (a < 0xd000) return wram[a - 0xc000] & 0xff;
126|    if (a < 0xe000) {
127|      if (!isCgb) return wram[a - 0xc000] & 0xff;
128|      return wram[wramBank() * 0x1000 + (a - 0xd000)] & 0xff;
129|    }
130|    if (a < 0xf000) {
131|      if (!isCgb) return wram[a - 0xe000] & 0xff;
132|      return wram[a - 0xe000] & 0xff;
133|    }
134|    if (a < 0xfe00) {
135|      if (!isCgb) return wram[a - 0xe000] & 0xff;
136|      // echo of bank-selected area
137|      const off = a - 0xf000;
138|      if (off < 0x1000) return wram[off] & 0xff;
139|      return wram[wramBank() * 0x1000 + (off - 0x1000)] & 0xff;
140|    }
141|    if (a < 0xfea0) {
142|      if (dmaOn) return 0xff;
143|      return ppu.oam[a - 0xfe00] & 0xff;
144|    }
145|    if (a < 0xff00) return 0xff;
146|    if (a < 0xff80) return ioRead(a);
147|    if (a < 0xffff) return hram[a - 0xff80] & 0xff;
148|    return IE & 0xff;
149|  }
150|
151|  function wrMem(a: number, v: number): void {
152|    v &= 0xff;
153|    a &= 0xffff;
154|    if (a < 0x8000) { cart.write(a, v); return; }
155|    if (a < 0xa000) {
156|      if (!isCgb) { ppu.vram[a - 0x8000] = v; return; }
157|      const b = vbk ? 0x2000 : 0;
158|      ppu.vram[b + (a - 0x8000)] = v; return;
159|    }
160|    if (a < 0xc000) { cart.writeRam(a, v); return; }
161|    if (a < 0xd000) { if (!isCgb) wram[a - 0xc000] = v; else wram[a - 0xc000] = v; return; }
162|    if (a < 0xe000) {
163|      if (!isCgb) { wram[a - 0xc000] = v; return; }
164|      wram[wramBank() * 0x1000 + (a - 0xd000)] = v; return;
165|    }
166|    if (a < 0xf000) {
167|      if (!isCgb) { wram[a - 0xe000] = v; return; }
168|      wram[a - 0xe000] = v; return;
169|    }
170|    if (a < 0xfe00) {
171|      if (!isCgb) { wram[a - 0xe000] = v; return; }
172|      const off = a - 0xf000;
173|      if (off < 0x1000) wram[off] = v;
174|      else wram[wramBank() * 0x1000 + (off - 0x1000)] = v;
175|      return;
176|    }
177|    if (a < 0xfea0) {
178|      if (!dmaOn) ppu.oam[a - 0xfe00] = v;
179|      return;
180|    }
181|    if (a < 0xff00) return;
182|    if (a < 0xff80) { ioWrite(a, v); return; }
183|    if (a < 0xffff) { hram[a - 0xff80] = v; return; }
184|    IE = v & 0xff;
185|  }
186|
187|  function peek(a: number): number {
188|    a &= 0xffff;
189|    if (a < 0x8000) return cart.read(a);
190|    if (a < 0xa000) {
191|      if (!isCgb) return ppu.vram[a - 0x8000] & 0xff;
192|      const b = vbk ? 0x2000 : 0;
193|      return ppu.vram[b + (a - 0x8000)] & 0xff;
194|    }
195|    if (a < 0xc000) return cart.readRam(a);
196|    if (a < 0xd000) return wram[a - 0xc000] & 0xff;
197|    if (a < 0xe000) {
198|      if (!isCgb) return wram[a - 0xc000] & 0xff;
199|      return wram[wramBank() * 0x1000 + (a - 0xd000)] & 0xff;
200|    }
201|    if (a < 0xf000) return wram[a - 0xe000] & 0xff;
202|    if (a < 0xfe00) {
203|      if (!isCgb) return wram[a - 0xe000] & 0xff;
204|      const off = a - 0xf000;
205|      if (off < 0x1000) return wram[off] & 0xff;
206|      return wram[wramBank() * 0x1000 + (off - 0x1000)] & 0xff;
207|    }
208|    if (a < 0xfea0) {
209|      if (dmaOn) return 0xff;
210|      return ppu.oam[a - 0xfe00] & 0xff;
211|    }
212|    if (a < 0xff00) return 0xff;
213|    if (a < 0xff80) return ioRead(a);
214|    if (a < 0xffff) return hram[a - 0xff80] & 0xff;
215|    return IE & 0xff;
216|  }
217|
218|  function ioRead(a: number): number {
219|    switch (a) {
220|      case 0xff00: {
221|        const sel = p1 & 0x30;
222|        const dir = (joyMask & 0x0f);
223|        const btn = ((joyMask >> 4) & 0x0f);
224|        let v = 0x0f;
225|        if ((sel & 0x10) === 0) v &= (~dir) & 0x0f;
226|        if ((sel & 0x20) === 0) v &= (~btn) & 0x0f;
227|        if ((sel & 0x30) === 0x30) v = 0x0f;
228|        return 0xc0 | (sel & 0x30) | (v & 0x0f);
229|      }
230|      case 0xff01: return sb & 0xff;
231|      case 0xff02: return (sc & 0xff) | 0x7c;
232|      case 0xff04: return (div >> 8) & 0xff;
233|      case 0xff05: return tima & 0xff;
234|      case 0xff06: return tma & 0xff;
235|      case 0xff07: return 0xf8 | (tac & 0x07);
236|      case 0xff0f: return 0xe0 | (IF & 0x1f);
237|      case 0xff46: return 0xff;
238|      case 0xff40: case 0xff41: case 0xff42: case 0xff43: case 0xff44:
239|      case 0xff45: case 0xff47: case 0xff48: case 0xff49: case 0xff4a: case 0xff4b:
240|        return ppu.readReg(a);
241|      default:
242|        if (a >= 0xff10 && a <= 0xff3f) {
243|          return audio[a - 0xff00] & 0xff;
244|        }
245|        if (!isCgb) return 0xff;
246|        switch (a) {
247|          case 0xff4d: return (0x7e | (key1arm ? 0x01 : 0) | (dbl ? 0x80 : 0)) & 0xff;
248|          case 0xff4f: return (0xfe | (vbk & 1)) & 0xff;
249|          case 0xff51: return hdma1 & 0xff;
250|          case 0xff52: return hdma2 & 0xff;
251|          case 0xff53: return hdma3 & 0xff;
252|          case 0xff54: return hdma4 & 0xff;
253|          case 0xff55:
254|            if (hdmaActive) return (hdmaRem - 1) & 0x7f;
255|            if (hdmaRem === 0) return 0xff;
256|            return (0x80 | ((hdmaRem - 1) & 0x7f)) & 0xff;
257|          case 0xff68: return (ppu.bgpi & 0xff) | 0x40;
258|          case 0xff69: return ppu.bgPal[ppu.bgpi & 0x3f] & 0xff;
259|          case 0xff6a: return (ppu.obpi & 0xff) | 0x40;
260|          case 0xff6b: return ppu.objPal[ppu.obpi & 0x3f] & 0xff;
261|          case 0xff70: return (0xf8 | (svbk & 0x07)) & 0xff;
262|          default: return 0xff;
263|        }
264|    }
265|  }
266|
267|  function hdmaCopyBlock(): void {
268|    for (let i = 0; i < 16; i++) {
269|      const s = (hdmaSrc + i) & 0xffff;
270|      const d = 0x8000 + ((hdmaDst + i) & 0x1ff0);
271|      const b = rdMem(s);
272|      const bank = vbk ? 0x2000 : 0;
273|      void bank;
274|      // destination is in current VBK bank, masked to 8000-9FF0
275|      ppu.vram[(vbk ? 0x2000 : 0) + ((hdmaDst + i) & 0x1ff0)] = b;
276|      void d;
277|    }
278|    hdmaSrc = (hdmaSrc + 16) & 0xffff;
279|    hdmaDst = (hdmaDst + 16) & 0x1fff;
280|    // keep register mirrors advancing (low nibbles read as 0? keep raw increment masked)
281|    hdma1 = (hdmaSrc >> 8) & 0xff;
282|    hdma2 = (hdmaSrc & 0xf0) | (hdma2 & 0x0f);
283|    hdma3 = (hdmaDst >> 8) & 0xff;
284|    hdma4 = (hdmaDst & 0xf0) | (hdma4 & 0x0f);
285|  }
286|
287|  function ioWrite(a: number, v: number): void {
288|    v &= 0xff;
289|    switch (a) {
290|      case 0xff00: p1 = (0xc0 | (v & 0x30) | 0x0f) & 0xff; break;
291|      case 0xff01: sb = v; break;
292|      case 0xff02: {
293|        sc = v;
294|        if ((v & 0x81) === 0x81) {
295|          serialText += String.fromCharCode(sb & 0xff);
296|          sb = 0xff;
297|          raise(3);
298|        }
299|        break;
300|      }
301|      case 0xff04: {
302|        div = 0;
303|        const c = curAnd();
304|        if (prevAnd === 1 && c === 0) { if (reload === 0) incTima(); }
305|        prevAnd = c;
306|        break;
307|      }
308|      case 0xff05:
309|        if (reload > 0) reload = 0;
310|        tima = v;
311|        break;
312|      case 0xff06: tma = v; break;
313|      case 0xff07: {
314|        tac = (v & 0x07) | 0xf8;
315|        const c = curAnd();
316|        if (prevAnd === 1 && c === 0) { if (reload === 0) incTima(); }
317|        prevAnd = c;
318|        break;
319|      }
320|      case 0xff0f: IF = 0xe0 | (v & 0x1f); break;
321|      case 0xff46: {
322|        dmaOn = true; dmaBase = (v << 8) & 0xffff; dmaPos = 0; dmaT = 0;
323|        break;
324|      }
325|      case 0xff40: case 0xff41: case 0xff42: case 0xff43: case 0xff45:
326|      case 0xff47: case 0xff48: case 0xff49: case 0xff4a: case 0xff4b:
327|        ppu.writeReg(a, v, raise);
328|        break;
329|      case 0xff44: break;
330|      default:
331|        if (a >= 0xff10 && a <= 0xff3f) { audio[a - 0xff00] = v; break; }
332|        if (!isCgb) break;
333|        switch (a) {
334|          case 0xff4d: key1arm = (v & 0x01) !== 0; break;
335|          case 0xff4f: vbk = v & 0x01; break;
336|          case 0xff51: hdma1 = v; hdmaSrc = ((hdma1 << 8) | (hdma2 & 0xf0)) & 0xffff; break;
337|          case 0xff52: hdma2 = v; hdmaSrc = ((hdma1 << 8) | (hdma2 & 0xf0)) & 0xffff; break;
338|          case 0xff53: hdma3 = v & 0x1f; hdmaDst = (((hdma3 & 0x1f) << 8) | (hdma4 & 0xf0)) & 0x1fff; break;
339|          case 0xff54: hdma4 = v; hdmaDst = (((hdma3 & 0x1f) << 8) | (hdma4 & 0xf0)) & 0x1fff; break;
340|          case 0xff55: {
341|            if ((v & 0x80) === 0) {
342|              if (hdmaActive) {
343|                hdmaActive = false;
344|                // stopped: keep hdmaRem for read with bit7 set
345|              } else {
346|                // GDMA
347|                const blocks = (v & 0x7f) + 1;
348|                hdmaSrc = ((hdma1 << 8) | (hdma2 & 0xf0)) & 0xffff;
349|                hdmaDst = (((hdma3 & 0x1f) << 8) | (hdma4 & 0xf0)) & 0x1fff;
350|                for (let b = 0; b < blocks; b++) {
351|                  for (let i = 0; i < 16; i++) {
352|                    const s = (hdmaSrc + b * 16 + i) & 0xffff;
353|                    const bb = rdMem(s);
354|                    ppu.vram[(vbk ? 0x2000 : 0) + ((hdmaDst + b * 16 + i) & 0x1ff0)] = bb;
355|                    tick(dbl ? 1 : 2);
356|                  }
357|                }
358|                hdmaSrc = (hdmaSrc + blocks * 16) & 0xffff;
359|                hdmaDst = (hdmaDst + blocks * 16) & 0x1fff;
360|                hdma1 = 0xff; hdma2 = 0xff; hdma3 = 0xff; hdma4 = 0xff;
361|                hdmaRem = 0;
362|                hdmaActive = false;
363|              }
364|            } else {
365|              if (hdmaActive) break;
366|              const blocks = (v & 0x7f) + 1;
367|              hdmaSrc = ((hdma1 << 8) | (hdma2 & 0xf0)) & 0xffff;
368|              hdmaDst = (((hdma3 & 0x1f) << 8) | (hdma4 & 0xf0)) & 0x1fff;
369|              hdmaRem = blocks;
370|              hdmaActive = true;
371|            }
372|            break;
373|          }
374|          case 0xff68: ppu.bgpi = v & 0xff; break;
375|          case 0xff69: {
376|            ppu.bgPal[ppu.bgpi & 0x3f] = v;
377|            if ((ppu.bgpi & 0x80) !== 0) ppu.bgpi = (0x80 | ((ppu.bgpi + 1) & 0x3f)) & 0xff;
378|            break;
379|          }
380|          case 0xff6a: ppu.obpi = v & 0xff; break;
381|          case 0xff6b: {
382|            ppu.objPal[ppu.obpi & 0x3f] = v;
383|            if ((ppu.obpi & 0x80) !== 0) ppu.obpi = (0x80 | ((ppu.obpi + 1) & 0x3f)) & 0xff;
384|            break;
385|          }
386|          case 0xff70: svbk = v & 0x07; break;
387|          default: break;
388|        }
389|        break;
390|    }
391|  }
392|
393|  function dmaStep(): void {
394|    if (!dmaOn) return;
395|    dmaT++;
396|    if (dmaT >= 4) {
397|      dmaT = 0;
398|      const src = (dmaBase + dmaPos) & 0xffff;
399|      let b = 0xff;
400|      if (src < 0x8000) b = cart.read(src);
401|      else if (src < 0xa000) {
402|        if (!isCgb) b = ppu.vram[src - 0x8000];
403|        else b = ppu.vram[(vbk ? 0x2000 : 0) + (src - 0x8000)];
404|      }
405|      else if (src < 0xc000) b = cart.readRam(src);
406|      else if (src < 0xd000) b = wram[src - 0xc000];
407|      else if (src < 0xe000) {
408|        if (!isCgb) b = wram[src - 0xc000];
409|        else b = wram[wramBank() * 0x1000 + (src - 0xd000)];
410|      }
411|      else if (src < 0xf000) b = wram[src - 0xe000];
412|      else if (src < 0xfe00) {
413|        if (!isCgb) b = wram[src - 0xe000];
414|        else {
415|          const off = src - 0xf000;
416|          if (off < 0x1000) b = wram[off];
417|          else b = wram[wramBank() * 0x1000 + (off - 0x1000)];
418|        }
419|      }
420|      else if (src < 0xfea0) b = ppu.oam[src - 0xfe00];
421|      else if (src < 0xff00) b = 0xff;
422|      else if (src < 0xff80) b = ioRead(src);
423|      else if (src < 0xffff) b = hram[src - 0xff80];
424|      else b = IE;
425|      ppu.oam[dmaPos] = b & 0xff;
426|      hits["dma"] = (hits["dma"] || 0) + 1;
427|      dmaPos++;
428|      if (dmaPos >= 160) { dmaOn = false; }
429|    }
430|  }
431|
432|  function doHdmaHblank(): void {
433|    if (!isCgb || !hdmaActive) return;
434|    if (!ppu.on) return;
435|    if (ppu.ly >= 144) return;
436|    hdmaCopyBlock();
437|    hits["dma"] = (hits["dma"] || 0) + 1;
438|    hdmaRem--;
439|    if (hdmaRem <= 0) { hdmaRem = 0; hdmaActive = false; hdma1 = 0xff; hdma2 = 0xff; hdma3 = 0xff; hdma4 = 0xff; }
440|  }
441|
442|  function tick(n: number): void {
443|    if (!isCgb || !dbl) {
444|      for (let i = 0; i < n; i++) {
445|        cycles++;
446|        timerStep();
447|        const wasMode = ppu.mode;
448|        const wasLy = ppu.ly;
449|        void wasLy;
450|        ppu.tick1(raise);
451|        if (ppu.mode === 0 && wasMode !== 0 && ppu.ly < 144) doHdmaHblank();
452|        dmaStep();
453|      }
454|    } else {
455|      // double speed: PPU advances 1 dot per tick, timer/DMA advance 2x
456|      for (let i = 0; i < n; i++) {
457|        cycles++;
458|        timerStep();
459|        timerStep();
460|        const wasMode = ppu.mode;
461|        ppu.tick1(raise);
462|        if (ppu.mode === 0 && wasMode !== 0 && ppu.ly < 144) doHdmaHblank();
463|        dmaStep();
464|        dmaStep();
465|      }
466|    }
467|  }
468|
469|  function poke(a: number, v: number): void {
470|    v &= 0xff;
471|    a &= 0xffff;
472|    if (a < 0x8000) { cart.write(a, v); return; }
473|    if (a < 0xa000) {
474|      if (!isCgb) { ppu.vram[a - 0x8000] = v; return; }
475|      ppu.vram[(vbk ? 0x2000 : 0) + (a - 0x8000)] = v; return;
476|    }
477|    if (a < 0xc000) { cart.writeRam(a, v); return; }
478|    if (a < 0xd000) { wram[a - 0xc000] = v; return; }
479|    if (a < 0xe000) {
480|      if (!isCgb) { wram[a - 0xc000] = v; return; }
481|      wram[wramBank() * 0x1000 + (a - 0xd000)] = v; return;
482|    }
