1|// The §6.1–§6.3 contract of core/index.ts, read on the bug-surface game (game/game.gb, built by S4).
2|import assert from "node:assert/strict";
3|import { createHash } from "node:crypto";
4|import { existsSync, readFileSync } from "node:fs";
5|import { resolve } from "node:path";
6|import { test } from "node:test";
7|import { GAME_RAM } from "../src/schema.ts";
8|import type { Core, CreateCore, Handlers } from "../src/schema.ts";
9|import { createCore as createCoreImpl, HANDLERS as HANDLERS_IMPL } from "./index.ts";
10|
11|const createCore: CreateCore = createCoreImpl;
12|const HANDLERS: Handlers = HANDLERS_IMPL;
13|const ROOT = resolve(import.meta.dirname, "..");
14|const GAME = resolve(ROOT, "game", "game.gb");
15|const rom = (): Uint8Array => new Uint8Array(readFileSync(GAME));
16|
17|/** Frames before the snapshot: past boot and the title's first VBlanks. */
18|const WARMUP_FRAMES = 120;
19|/** Frames after the snapshot that both runs must agree on (SPEC §5 S1 Accept). */
20|const RESUME_FRAMES = 1000;
21|
22|/** An input schedule keyed by frame index, so the resumed run is fed the same buttons as the straight one. */
23|const buttonsAt = (f: number): number => ((f >> 6) & 1 ? 0x80 : 0) | ((f >> 4) & 1 ? 0x01 : 0) | ((f >> 5) & 1 ? 0x10 : 0);
24|
25|function fingerprint(core: Core): string {
26|  const h = createHash("sha256");
27|  h.update(core.frame());
28|  h.update(JSON.stringify({ cpu: core.cpu, cycles: core.cycles, serial: core.serial }));
29|  h.update(core.snapshot());
30|  return h.digest("hex");
31|}
32|
33|function runFrames(core: Core, from: number, count: number, perFrame?: (f: number) => void): void {
34|  for (let f = from; f < from + count; f++) {
35|    core.setButtons(buttonsAt(f));
36|    core.runFrame();
37|    perFrame?.(f);
38|  }
39|}
40|
41|test("restore(snapshot()) into a fresh core followed by 1,000 frames equals the straight run's frame, registers, cycles and snapshot", () => {
42|  const straight = createCore(rom());
43|  runFrames(straight, 0, WARMUP_FRAMES);
44|  const snap = straight.snapshot();
45|  const resumedFrames: string[] = [];
46|  const straightFrames: string[] = [];
47|  runFrames(straight, WARMUP_FRAMES, RESUME_FRAMES, () => straightFrames.push(createHash("sha1").update(straight.frame()).digest("hex")));
48|
49|  const resumed = createCore(rom());
50|  resumed.restore(snap);
51|  runFrames(resumed, WARMUP_FRAMES, RESUME_FRAMES, () => resumedFrames.push(createHash("sha1").update(resumed.frame()).digest("hex")));
52|
53|  assert.deepEqual(resumedFrames, straightFrames);
54|  assert.equal(fingerprint(resumed), fingerprint(straight));
55|});
56|
57|test("HANDLERS holds every handler id the tap emits over 600 frames of the game, each mapped to an existing core/ file", () => {
58|  const core = createCore(rom());
59|  const emitted = new Set<string>();
60|  runFrames(core, 0, 600, () => { for (const [id, n] of Object.entries(core.tap.handlerHits())) if (n > 0) emitted.add(id); });
61|  assert.ok(emitted.size > 0, "the tap emitted no handler id");
62|  const missing = [...emitted].filter((id) => !(id in HANDLERS));
63|  assert.deepEqual(missing, []);
64|  for (const [id, file] of Object.entries(HANDLERS)) {
65|    assert.match(file, /^core\//, `${id} → ${file}`);
66|    assert.ok(existsSync(resolve(ROOT, file)), `${id} → ${file} does not exist`);
67|  }
68|});
69|
70|test("handlerHits resets on read: a second read with no step between returns no positive count", () => {
71|  const core = createCore(rom());
72|  core.runFrame();
73|  core.tap.handlerHits();
74|  assert.deepEqual(Object.values(core.tap.handlerHits()).filter((n) => n > 0), []);
75|});
76|
77|test("runToCounter(n) stops with the game's LE16 counter at 0xC0F0 equal to n, and returns false on a stalled counter", () => {
78|  const core = createCore(rom());
79|  assert.equal(core.runToCounter(200), true);
80|  assert.equal(core.read(GAME_RAM.counter) | (core.read(GAME_RAM.counter + 1) << 8), 200);
81|  // The lives byte holds still on the title with no buttons pressed, so the run stalls and returns false.
82|  assert.equal(core.runToCounter(0x1234, GAME_RAM.lives), false);
83|});
84|
85|test("runFrame ends at LY 144 and advances 70,224 T-cycles per frame on a running LCD", () => {
86|  const core = createCore(rom());
87|  core.runToCounter(60);
88|  core.runFrame();
89|  const c0 = core.cycles;
90|  core.runFrame();
91|  assert.equal(core.tap.ppu().ly, 144);
92|  const dt = core.cycles - c0;
93|  assert.ok(Math.abs(dt - 70_224) <= 24, `frame took ${dt} T-cycles`);
94|  assert.equal(core.frame().length, 160 * 144);
95|});

