15|  dot = 0; mode: 0 | 1 | 2 | 3 = 2; winLine = 0; statLine = false;
16|  m3len = 172; lineSprites: number[] = [];
17|  hits: Record<HandlerId, number>;
18|  constructor(hits: Record<HandlerId, number>) { this.hits = hits; this.resetStatLine(); }
19|  get on(): boolean { return (this.lcdc & 0x80) !== 0; }
20|  resetStatLine(): void { this.statLine = this.computeStatLine(); }
21|  computeStatLine(): boolean {
22|    if (!this.on) return false;
23|    const s = this.stat;
24|    const lycEq = (this.stat & 0x04) !== 0;
25|    if ((s & 0x40) && lycEq) return true;
26|    if ((s & 0x20) && this.mode === 2) return true;
