9|import { createCore as createCoreImpl, HANDLERS as HANDLERS_IMPL } from "./index.ts";
10|
11|const createCore: CreateCore = createCoreImpl;
12|const HANDLERS: Handlers = HANDLERS_IMPL;
13|const ROOT = resolve(import.meta.dirname, "..");
14|const GAME = resolve(ROOT, "game", "game.gb");
15|const rom = (): Uint8Array => new Uint8Array(readFileSync(GAME));
16|
17|/** Frames before the snapshot: past boot and the title's first VBlanks. */
18|const WARMUP_FRAMES = 120;
19|/** Frames after the snapshot that both runs must agree on (SPEC §5 S1 Accept). */
20|const RESUME_FRAMES = 1000;
21|
22|/** An input schedule keyed by frame index, so the resumed run is fed the same buttons as the straight one. */
23|const buttonsAt = (f: number): number => ((f >> 6) & 1 ? 0x80 : 0) | ((f >> 4) & 1 ? 0x01 : 0) | ((f >> 5) & 1 ? 0x10 : 0);
24|
25|function fingerprint(core: Core): string {
26|  const h = createHash("sha256");
27|  h.update(core.frame());
28|  h.update(JSON.stringify({ cpu: core.cpu, cycles: core.cycles, serial: core.serial }));
29|  h.update(core.snapshot());
30|  return h.digest("hex");
31|}
32|
33|function runFrames(core: Core, from: number, count: number, perFrame?: (f: number) => void): void {
34|  for (let f = from; f < from + count; f++) {
35|    core.setButtons(buttonsAt(f));
36|    core.runFrame();
37|    perFrame?.(f);
38|  }
39|}
40|
41|test("restore(snapshot()) into a fresh core followed by 1,000 frames equals the straight run's frame, registers, cycles and snapshot", () => {
42|  const straight = createCore(rom());
43|  runFrames(straight, 0, WARMUP_FRAMES);
44|  const snap = straight.snapshot();
45|  const resumedFrames: string[] = [];
46|  const straightFrames: string[] = [];
47|  runFrames(straight, WARMUP_FRAMES, RESUME_FRAMES, () => straightFrames.push(createHash("sha1").update(straight.frame()).digest("hex")));
48|
49|  const resumed = createCore(rom());
50|  resumed.restore(snap);
51|  runFrames(resumed, WARMUP_FRAMES, RESUME_FRAMES, () => resumedFrames.push(createHash("sha1").update(resumed.frame()).digest("hex")));
52|
53|  assert.deepEqual(resumedFrames, straightFrames);
54|  assert.equal(fingerprint(resumed), fingerprint(straight));
55|});
