57|test("HANDLERS holds every handler id the tap emits over 600 frames of the game, each mapped to an existing core/ file", () => {
58|  const core = createCore(rom());
59|  const emitted = new Set<string>();
60|  runFrames(core, 0, 600, () => { for (const [id, n] of Object.entries(core.tap.handlerHits())) if (n > 0) emitted.add(id); });
61|  assert.ok(emitted.size > 0, "the tap emitted no handler id");
62|  const missing = [...emitted].filter((id) => !(id in HANDLERS));
