// minimal PNG decoder (8-bit, non-interlaced) -> {w,h,data RGBA}
import { readFileSync } from "node:fs";
import { inflateSync } from "node:zlib";
export function decodePng(path) {
  const d = readFileSync(path);
  let pos = 8; const idat = [];
  let w,h,bitd,ctype;
  while (pos < d.length) {
    const ln = d.readUInt32BE(pos); const typ = d.toString("ascii", pos+4, pos+8);
    const dat = d.subarray(pos+8, pos+8+ln); pos += 8+ln+4;
    if (typ==="IHDR") { w=dat.readUInt32BE(0); h=dat.readUInt32BE(4); bitd=dat[8]; ctype=dat[9]; }
    else if (typ==="IDAT") idat.push(dat);
    else if (typ==="IEND") break;
  }
  const raw = inflateSync(Buffer.concat(idat));
  const ch = {0:1,2:3,3:1,4:2,6:4}[ctype];
  const stride = w*ch; const px = Buffer.alloc(w*h*ch);
  let prev = Buffer.alloc(stride); let p=0;
  for (let y=0;y<h;y++) {
    const f=raw[p++];
    const line=Buffer.from(raw.subarray(p,p+stride)); p+=stride;
    if (f===1) for(let i=ch;i<stride;i++) line[i]=(line[i]+line[i-ch])&0xff;
    else if (f===2) for(let i=0;i<stride;i++) line[i]=(line[i]+prev[i])&0xff;
    else if (f===3) for(let i=0;i<stride;i++) line[i]=(line[i]+((prev[i]+(i>=ch?line[i-ch]:0))>>1))&0xff;
    else if (f===4) for(let i=0;i<stride;i++){const a=i>=ch?line[i-ch]:0,b=prev[i],c=i>=ch?prev[i-ch]:0;const pp=a+b-c,pa=Math.abs(pp-a),pb=Math.abs(pp-b),pc=Math.abs(pp-c);line[i]=(line[i]+(pa<=pb&&pa<=pc?a:(pb<=pc?b:c)))&0xff;}
    line.copy(px,y*stride); prev=line;
  }
  return {w,h,ctype,data:px};
}
