252|          this.rgb[oo] = (r << 3) | (r >> 2);
253|          this.rgb[oo + 1] = (g << 3) | (g >> 2);
254|          this.rgb[oo + 2] = (bl << 3) | (bl >> 2);
255|        }
256|      }
257|    }
258|  }
259|  tick(t: number, raise: (b: number) => void): void {
260|    for (let i = 0; i < t; i++) this.tick1(raise);
261|  }
262|  tick1(raise: (b: number) => void): void {
263|    if (!this.on) return;
264|    const prevMode = this.mode;
265|    void prevMode;
266|    this.dot++;
267|    if (this.ly < 144) {
268|      const m3end = 80 + this.m3len;
269|      let nm: 0 | 1 | 2 | 3 = this.mode;
270|      if (this.dot <= 80) nm = 2; else if (this.dot <= m3end) nm = 3; else nm = 0;
