279|        if (this.ly === 144) {
280|          this.mode = 1; this.stat = (this.stat & ~0x03) | 1;
281|          raise(0); this.checkStat(raise);
282|        } else {
283|          this.mode = 2; this.stat = (this.stat & ~0x03) | 2;
284|          this.checkStat(raise); this.beginLine(raise);
285|        }
286|      }
287|    } else {
288|      this.mode = 1; this.stat = (this.stat & ~0x03) | 1;
289|      if (this.dot >= 456) {
290|        this.dot = 0; this.ly++;
