218|  function ioRead(a: number): number {
219|    switch (a) {
220|      case 0xff00: {
221|        const sel = p1 & 0x30;
222|        const dir = (joyMask & 0x0f);
223|        const btn = ((joyMask >> 4) & 0x0f);
