231|      case 0xff02: return (sc & 0xff) | 0x7c;
232|      case 0xff04: return (div >> 8) & 0xff;
233|      case 0xff05: return tima & 0xff;
234|      case 0xff06: return tma & 0xff;
235|      case 0xff07: return 0xf8 | (tac & 0x07);
236|      case 0xff0f: return 0xe0 | (IF & 0x1f);
237|      case 0xff46: return 0xff;
238|      case 0xff40: case 0xff41: case 0xff42: case 0xff43: case 0xff44:
239|      case 0xff45: case 0xff47: case 0xff48: case 0xff49: case 0xff4a: case 0xff4b:
