347|                const blocks = (v & 0x7f) + 1;
348|                hdmaSrc = ((hdma1 << 8) | (hdma2 & 0xf0)) & 0xffff;
349|                hdmaDst = (((hdma3 & 0x1f) << 8) | (hdma4 & 0xf0)) & 0x1fff;
