378|            break;
379|          }
380|          case 0xff6a: ppu.obpi = v & 0xff; break;
381|          case 0xff6b: {
382|            ppu.objPal[ppu.obpi & 0x3f] = v;
383|            if ((ppu.obpi & 0x80) !== 0) ppu.obpi = (0x80 | ((ppu.obpi + 1) & 0x3f)) & 0xff;
384|            break;
385|          }
386|          case 0xff70: svbk = v & 0x07; break;
387|          default: break;
388|        }
389|        break;
390|    }
391|  }
392|
393|  function dmaStep(): void {
394|    if (!dmaOn) return;
395|    dmaT++;
396|    if (dmaT >= 4) {
397|      dmaT = 0;
398|      const src = (dmaBase + dmaPos) & 0xffff;
399|      let b = 0xff;
400|      if (src < 0x8000) b = cart.read(src);
401|      else if (src < 0xa000) {
402|        if (!isCgb) b = ppu.vram[src - 0x8000];
403|        else b = ppu.vram[(vbk ? 0x2000 : 0) + (src - 0x8000)];
404|      }
405|      else if (src < 0xc000) b = cart.readRam(src);
406|      else if (src < 0xd000) b = wram[src - 0xc000];
407|      else if (src < 0xe000) {
408|        if (!isCgb) b = wram[src - 0xc000];
409|        else b = wram[wramBank() * 0x1000 + (src - 0xd000)];
410|      }
411|      else if (src < 0xf000) b = wram[src - 0xe000];
412|      else if (src < 0xfe00) {
413|        if (!isCgb) b = wram[src - 0xe000];
414|        else {
415|          const off = src - 0xf000;
416|          if (off < 0x1000) b = wram[off];
417|          else b = wram[wramBank() * 0x1000 + (off - 0x1000)];
418|        }
419|      }
420|      else if (src < 0xfea0) b = ppu.oam[src - 0xfe00];
421|      else if (src < 0xff00) b = 0xff;
422|      else if (src < 0xff80) b = ioRead(src);
423|      else if (src < 0xffff) b = hram[src - 0xff80];
424|      else b = IE;
425|      ppu.oam[dmaPos] = b & 0xff;
426|      hits["dma"] = (hits["dma"] || 0) + 1;
427|      dmaPos++;
428|      if (dmaPos >= 160) { dmaOn = false; }
429|    }
430|  }
